// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { graphSvg, graphTurtle } from "../../../main/frontend/graph-explorer/graph-export.ts";
import { exportFixtureGraph } from "../../../../scripts/export-query-fixtures.mjs";

test("the loaded statements export as Turtle, grouped by subject, with the usual prefixes and RDF 1.2 triple terms", () => {
  assert.equal(
    graphTurtle(exportFixtureGraph()),
    `@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix schema: <http://schema.org/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/alice> a schema:Person ;
    rdfs:label "Alice \\"Al\\" Smith"@en, "line\\nbreak" ;
    schema:age "39"^^xsd:integer ;
    schema:knows <http://example.org/bob>, _:b1 ;
    <http://example.org/odd#name.> "x" .

<http://example.org/bob> schema:worksFor <http://example.org/acme%20corp> .

<http://example.org/claim> rdf:reifies <<( <http://example.org/alice> schema:knows <http://example.org/bob> )>> .

_:b1 rdfs:label "Somebody" .
`,
  );
});

test("an empty graph exports as an empty document", () => {
  assert.equal(graphTurtle({ nodes: [], edges: [], revision: 0 }), "");
});

test("the drawn graph exports as a standalone SVG framed around its nodes", () => {
  const svg = graphSvg({
    nodes: [
      { id: "urn:a", label: "A & B", kind: "iri", types: [], x: 100, y: 50 },
      { id: "urn:b", label: "<B>", kind: "iri", types: [], x: 300, y: 50 },
    ],
    edges: [{ id: "e1", source: "urn:a", predicate: "urn:p", label: "knows", target: "urn:b" }],
    curves: new Map([["e1", { path: "M150,50 Q200,40 250,50", start: { x: 150, y: 50 }, control: { x: 200, y: 40 }, end: { x: 250, y: 50 } }]]),
    labels: new Map([["e1", { point: { x: 200, y: 40 }, anchor: { x: 200, y: 45 } }]]),
    color: (value) => value.replace(/^var\((--[\w-]+)\)$/, "[$1]"),
    palette: { background: "#fff", edge: "#999", nodeText: "#111", labelText: "#333", labelFill: "#eee", font: "Inter" },
  });
  assert.match(svg, /^<svg xmlns="http:\/\/www\.w3\.org\/2000\/svg" viewBox="(-?[\d.]+ ){3}-?[\d.]+" width="\d+" height="\d+">/);
  assert.match(svg, /A &amp; B/);
  assert.match(svg, /&lt;B&gt;/);
  assert.match(svg, /<path d="M150,50 Q200,40 250,50" fill="none" stroke="#999"/);
  assert.match(svg, /stroke="\[--graph-explorer-loading-stroke\]"/, "CSS variables are resolved for a standalone file");
  assert.match(svg, />knows<\/text>/);
  assert.doesNotMatch(svg, /var\(/);
});
